referenceFixTemplate:
public class Main {
    public static void main(String[] args) {
        int n = 0b{nb};
        int k = {k};

        System.out.println("原来这排：" + bits(n));
        System.out.println("第 " + k + " 位是 " + (n >> k & 1));
        System.out.println("关掉第 " + k + " 位：" + bits(n & ~(1 << k)));
    }

    static String bits(int n) {
        String s = Integer.toBinaryString(n & 0xFF);
        while (s.length() < 8) {
            s = "0" + s;
        }
        return s;
    }
}
